    const agentBadAdapter = makeTestAgent({
      id: "bad-adapter-agent",
      adapter: "nonexistent-adapter-xyz",
      dispatch: [{ on: "task.ready" }],
    });
    await setupProjectWithAgents(testDir, [agentBadAdapter]);

