    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.meta.yaml"),
      YAML.stringify({
        kynetic_meta: "1.0",
        agents: [{
          _ulid: agent._ulid,
          id: agent.id,
          name: agent.name,
          dispatch: [],
          concurrency: agent.concurrency,
          adapter: agent.adapter,
          auto_approve: false,
