describe("AC-4: kspec agent dispatch start with running daemon", () => {
  let testDir: string;
  let mockServer: Awaited<ReturnType<typeof startMockDaemon>> | null = null;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-agent-dispatch-start-");
  });

  afterEach(async () => {
    await mockServer?.cleanup();
    mockServer = null;
    await cleanupTempDir(testDir);
  });

  it("should start dispatch engine when daemon is running", async () => {
    let dispatchStartCalled = false;

    mockServer = await startMockDaemon({
      "/api/agent/dispatch/start": (_req, res) => {
        dispatchStartCalled = true;
        res.writeHead(200, { "Content-Type": "application/json" });
        res.end(JSON.stringify({
          started: true,
          status: { running: true, activeInvocations: 0, queuedInvocations: 0 },
        }));
      },
    });

    const fs_sync = require("node:fs");
