// ─── Mock daemon HTTP server helpers ─────────────────────────────────────────

interface MockDaemonServer {
  server: http.Server;
  port: number;
  configDir: string;
  cleanup: () => Promise<void>;
}

/**
 * Start a mock HTTP server that simulates the kspec daemon dispatch API.
 * Writes PID and port files to a temp config dir so getDaemonUrl() finds it.
 *
 * IMPORTANT: The CLI uses PidFileManager with default configDir (~/.config/kspec/),
 * so we write files there temporarily. Files are restored/removed on cleanup.
 */
async function startMockDaemon(
  handlers: Record<string, (req: http.IncomingMessage, res: http.ServerResponse) => void>,
): Promise<MockDaemonServer> {
  const server = http.createServer((req, res) => {
    const url = req.url ?? "/";
    const handler = handlers[url];
    if (handler) {
      // Buffer POST bodies
      let body = "";
      req.on("data", (chunk) => { body += chunk; });
      req.on("end", () => {
        (req as http.IncomingMessage & { body: string }).body = body;
        handler(req, res);
      });
    } else {
      res.writeHead(404);
      res.end(JSON.stringify({ error: "Not found" }));
    }
  });

  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const port = (server.address() as { port: number }).port;

  // Write PID/port files to the default kspec config dir so the CLI subprocess picks them up
  const kspecConfigDir = path.join(os.homedir(), ".config", "kspec");
  fsSync.mkdirSync(kspecConfigDir, { recursive: true });
  const pidFilePath = path.join(kspecConfigDir, "daemon.pid");
  const portFilePath = path.join(kspecConfigDir, "daemon.port");

  // Save existing files to restore them after test
  const savedPid = fsSync.existsSync(pidFilePath) ? fsSync.readFileSync(pidFilePath, "utf-8") : null;
  const savedPort = fsSync.existsSync(portFilePath) ? fsSync.readFileSync(portFilePath, "utf-8") : null;

  // Write our process PID (so isDaemonRunning() returns true) and mock port
  fsSync.writeFileSync(pidFilePath, process.pid.toString(), "utf-8");
  fsSync.writeFileSync(portFilePath, port.toString(), "utf-8");

  const cleanup = async (): Promise<void> => {
    await new Promise<void>((resolve) => server.close(() => resolve()));
    // Restore original files
    if (savedPid !== null) {
      fsSync.writeFileSync(pidFilePath, savedPid, "utf-8");
    } else if (fsSync.existsSync(pidFilePath)) {
      fsSync.unlinkSync(pidFilePath);
    }
    if (savedPort !== null) {
      fsSync.writeFileSync(portFilePath, savedPort, "utf-8");
    } else if (fsSync.existsSync(portFilePath)) {
      fsSync.unlinkSync(portFilePath);
    }
  };

  return { server, port, configDir: kspecConfigDir, cleanup };
}

