/**
 * CLI Agent Commands tests.
 *
 * Tests for kspec agent list, run, status, and dispatch subcommands.
 *
 * Task: @implement-cli-agent-commands
 * Spec: @cli-agent-commands
 */

import { describe, it, expect, beforeEach, afterEach, vi } from "vitest";
import * as path from "node:path";
import * as fs from "node:fs/promises";
import * as fsSync from "node:fs";
import * as http from "node:http";
import * as os from "node:os";
import * as YAML from "yaml";
import {
  createTempDir,
  cleanupTempDir,
  kspec,
  testUlid,
  initGitRepo,
} from "./helpers/cli.js";
import { runInvocation } from "../src/agent-runtime/invocation.js";
import { registerAdapter } from "../src/agents/adapters.js";
import type { Agent } from "../src/schema/meta.js";

// ─── Mock ACP for unit-level tests ───────────────────────────────────────────

const MOCK_ACP = path.join(__dirname, "mocks", "acp-mock.js");

function registerMockAdapter(): void {
  registerAdapter("mock-acp", {
    command: "node",
    args: [MOCK_ACP],
    env: { MOCK_ACP_PROJECT_DIR: process.cwd() },
    description: "Mock ACP adapter for testing",
  });
}

// ─── Mock daemon HTTP server helpers ─────────────────────────────────────────

interface MockDaemonServer {
  server: http.Server;
  port: number;
  configDir: string;
  cleanup: () => Promise<void>;
}

/**
 * Start a mock HTTP server that simulates the kspec daemon dispatch API.
 * Writes PID and port files to a temp config dir so getDaemonUrl() finds it.
 *
 * IMPORTANT: The CLI uses PidFileManager with default configDir (~/.config/kspec/),
 * so we write files there temporarily. Files are restored/removed on cleanup.
 */
async function startMockDaemon(
  handlers: Record<string, (req: http.IncomingMessage, res: http.ServerResponse) => void>,
): Promise<MockDaemonServer> {
  const server = http.createServer((req, res) => {
    const url = req.url ?? "/";
    const handler = handlers[url];
    if (handler) {
      // Buffer POST bodies
      let body = "";
      req.on("data", (chunk) => { body += chunk; });
      req.on("end", () => {
        (req as http.IncomingMessage & { body: string }).body = body;
        handler(req, res);
      });
    } else {
      res.writeHead(404);
      res.end(JSON.stringify({ error: "Not found" }));
    }
  });

  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const port = (server.address() as { port: number }).port;

  // Write PID/port files to the default kspec config dir so the CLI subprocess picks them up
  const kspecConfigDir = path.join(os.homedir(), ".config", "kspec");
  fsSync.mkdirSync(kspecConfigDir, { recursive: true });
  const pidFilePath = path.join(kspecConfigDir, "daemon.pid");
  const portFilePath = path.join(kspecConfigDir, "daemon.port");

  // Save existing files to restore them after test
  const savedPid = fsSync.existsSync(pidFilePath) ? fsSync.readFileSync(pidFilePath, "utf-8") : null;
  const savedPort = fsSync.existsSync(portFilePath) ? fsSync.readFileSync(portFilePath, "utf-8") : null;

  // Write our process PID (so isDaemonRunning() returns true) and mock port
  fsSync.writeFileSync(pidFilePath, process.pid.toString(), "utf-8");
  fsSync.writeFileSync(portFilePath, port.toString(), "utf-8");

  const cleanup = async (): Promise<void> => {
    await new Promise<void>((resolve) => server.close(() => resolve()));
    // Restore original files
    if (savedPid !== null) {
      fsSync.writeFileSync(pidFilePath, savedPid, "utf-8");
    } else if (fsSync.existsSync(pidFilePath)) {
      fsSync.unlinkSync(pidFilePath);
    }
    if (savedPort !== null) {
      fsSync.writeFileSync(portFilePath, savedPort, "utf-8");
    } else if (fsSync.existsSync(portFilePath)) {
      fsSync.unlinkSync(portFilePath);
    }
  };

  return { server, port, configDir: kspecConfigDir, cleanup };
}

// ─── Fixtures ────────────────────────────────────────────────────────────────

function makeTestAgent(overrides: Partial<Agent> = {}): Agent {
  return {
    _ulid: testUlid("AGNT"),
    id: "test-worker",
    name: "Test Worker Agent",
    capabilities: [],
    tools: [],
    conventions: [],
    dispatch: [{ on: "task.ready" }],
    skills: [],
    auto_approve: false,
    concurrency: { max_concurrent: 1 },
    adapter: "claude-agent-acp",
    ...overrides,
  };
}

/**
 * Set up a minimal kspec project directory with meta containing agents.
 * Uses traditional (non-shadow) layout.
 */
async function setupProjectWithAgents(
  dir: string,
  agents: Agent[],
): Promise<void> {
  initGitRepo(dir);

  await fs.writeFile(
    path.join(dir, "kynetic.yaml"),
    YAML.stringify({ kynetic: "1", title: "Test Project" }),
    "utf-8",
  );

  await fs.writeFile(
    path.join(dir, "kynetic.meta.yaml"),
    YAML.stringify({
      kynetic_meta: "1.0",
      agents: agents.map((a) => ({
        _ulid: a._ulid,
        id: a.id,
        name: a.name,
        description: a.description,
        dispatch: a.dispatch ?? [],
        concurrency: a.concurrency,
        adapter: a.adapter,
        budget: a.budget,
        auto_approve: a.auto_approve ?? false,
      })),
    }),
    "utf-8",
  );

  await fs.writeFile(
    path.join(dir, "project.tasks.yaml"),
    YAML.stringify({ tasks: [] }),
    "utf-8",
  );
}

// ─── AC-1: kspec agent list ───────────────────────────────────────────────────

// AC: @cli-agent-commands ac-1
describe("AC-1: kspec agent list", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-agent-list-");
  });

  afterEach(async () => {
    await cleanupTempDir(testDir);
  });

  it("should list all agent definitions with id, adapter, and concurrency", () => {
    const agent1 = makeTestAgent({ id: "worker-1", adapter: "claude-agent-acp" });
    const agent2 = makeTestAgent({
      _ulid: testUlid("AGNT", 2),
      id: "worker-2",
      adapter: "codex-acp",
    });

    // Set up project synchronously using YAML.stringify
    initGitRepo(testDir);
    const fs_sync = require("node:fs");
    const path_sync = require("node:path");
    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.yaml"),
      YAML.stringify({ kynetic: "1", title: "Test" }),
    );
    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.meta.yaml"),
      YAML.stringify({
        kynetic_meta: "1.0",
        agents: [agent1, agent2].map((a) => ({
          _ulid: a._ulid,
          id: a.id,
          name: a.name,
          dispatch: a.dispatch ?? [],
          concurrency: a.concurrency,
          adapter: a.adapter,
          auto_approve: false,
        })),
      }),
    );
    fs_sync.writeFileSync(
      path_sync.join(testDir, "project.tasks.yaml"),
      YAML.stringify({ tasks: [] }),
    );

    const result = kspec("agent list", testDir);

    expect(result.exitCode).toBe(0);
    expect(result.stdout).toContain("worker-1");
    expect(result.stdout).toContain("worker-2");
    expect(result.stdout).toContain("claude-agent-acp");
    expect(result.stdout).toContain("codex-acp");
  });

  it("should output JSON when --json flag is provided", () => {
    const agent = makeTestAgent({ id: "json-agent" });

    initGitRepo(testDir);
    const fs_sync = require("node:fs");
    const path_sync = require("node:path");
    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.yaml"),
      YAML.stringify({ kynetic: "1", title: "Test" }),
    );
    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.meta.yaml"),
      YAML.stringify({
        kynetic_meta: "1.0",
        agents: [{
          _ulid: agent._ulid,
          id: agent.id,
          name: agent.name,
          dispatch: agent.dispatch ?? [],
          concurrency: agent.concurrency,
          adapter: agent.adapter,
          auto_approve: false,
        }],
      }),
    );
    fs_sync.writeFileSync(
      path_sync.join(testDir, "project.tasks.yaml"),
      YAML.stringify({ tasks: [] }),
    );

    // AC: @trait-json-output ac-1 - valid JSON output
    const result = kspec("agent list --json", testDir);

    expect(result.exitCode).toBe(0);
    const data = JSON.parse(result.stdout);
    expect(data.items).toBeDefined();
    expect(data.total).toBeDefined();
    // AC: @trait-json-output ac-4 - references use @ prefix
    expect(data.items[0].id).toBe("json-agent");
  });

  it("should return 0 exit code with empty list when no agents defined", () => {
    initGitRepo(testDir);
    const fs_sync = require("node:fs");
    const path_sync = require("node:path");
    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.yaml"),
      YAML.stringify({ kynetic: "1", title: "Test" }),
    );
    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.meta.yaml"),
      YAML.stringify({ kynetic_meta: "1.0", agents: [] }),
    );
    fs_sync.writeFileSync(
      path_sync.join(testDir, "project.tasks.yaml"),
      YAML.stringify({ tasks: [] }),
    );

    // AC: @trait-semantic-exit-codes ac-5 - exit 0 with empty result
    const result = kspec("agent list", testDir);
    expect(result.exitCode).toBe(0);
    expect(result.stdout.toLowerCase()).toContain("no agent");
  });

  it("should support --count flag", () => {
    const agent = makeTestAgent();
    initGitRepo(testDir);
    const fs_sync = require("node:fs");
    const path_sync = require("node:path");
    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.yaml"),
      YAML.stringify({ kynetic: "1", title: "Test" }),
    );
    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.meta.yaml"),
      YAML.stringify({
        kynetic_meta: "1.0",
        agents: [{
          _ulid: agent._ulid,
          id: agent.id,
          name: agent.name,
          dispatch: agent.dispatch ?? [],
          concurrency: agent.concurrency,
          adapter: agent.adapter,
          auto_approve: false,
        }],
      }),
    );
    fs_sync.writeFileSync(
      path_sync.join(testDir, "project.tasks.yaml"),
      YAML.stringify({ tasks: [] }),
    );

    // AC: @trait-filterable-list ac-8 - count mode
    const result = kspec("agent list --count", testDir);
    expect(result.exitCode).toBe(0);
    expect(result.stdout.trim()).toBe("1");
  });
});

