  // Save existing files to restore them after test
  const savedPid = fsSync.existsSync(pidFilePath) ? fsSync.readFileSync(pidFilePath, "utf-8") : null;
  const savedPort = fsSync.existsSync(portFilePath) ? fsSync.readFileSync(portFilePath, "utf-8") : null;

