    const agent1 = makeTestAgent({ id: "worker-1", adapter: "claude-agent-acp" });
    const agent2 = makeTestAgent({
      _ulid: testUlid("AGNT", 2),
      id: "worker-2",
      adapter: "codex-acp",
    });

    // Set up project synchronously using YAML.stringify
    initGitRepo(testDir);
