    fs_sync.writeFileSync(
      path_sync.join(testDir, "kynetic.meta.yaml"),
      YAML.stringify({
        kynetic_meta: "1.0",
        agents: [agent1, agent2].map((a) => ({
          _ulid: a._ulid,
          id: a.id,
          name: a.name,
