    const fetchMock = vi.fn().mockResolvedValue({
      ok: true,
      json: async () => ({
        started: true,
        status: { running: true, activeInvocations: 0, queuedInvocations: 0 },
      }),
    } as Response);
    vi.stubGlobal("fetch", fetchMock);

    // Run the command programmatically
